#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=14

# The second half of #42, after scripts/setup-beta-infra.sh: the database,
# backups, API and web on Coolify, deploys from CI, a restore drill and the
# first preview APK. Reads and extends the provisioning wizard's file.
cd "$(dirname "${BASH_SOURCE[0]}")/.."
ENV_FILE=".env.production"
IMAGES="ghcr.io/baspinarenes"

# already_saved KEY...: when every KEY is already in ENV_FILE, load them and
# offer to skip the stage. Lets a re-run jump past finished work.
already_saved() {
  local k v
  for k in "$@"; do
    v=$(_existing "$k" || true)
    [[ -n "$v" ]] || return 1
    printf -v "$k" '%s' "$v"
  done
  note "Saved on an earlier run: $*"
  confirm "Skip this stage?"
}

# ask_match ask|ask_secret KEY "Prompt" REGEX "Hint": ask until the value
# matches REGEX, so a mis-paste is caught here rather than in production.
ask_match() {
  local fn="$1" key="$2" prompt="$3" re="$4" hint="$5"
  while :; do
    "$fn" "$key" "$prompt"
    [[ "${!key}" =~ $re ]] && return 0
    warn "$hint"
  done
}

# to_clipboard VALUE: put VALUE on the clipboard so it is pasted, not shown.
to_clipboard() {
  if   command -v pbcopy   >/dev/null 2>&1; then printf '%s' "$1" | pbcopy
  elif command -v wl-copy  >/dev/null 2>&1; then printf '%s' "$1" | wl-copy
  elif command -v xclip    >/dev/null 2>&1; then printf '%s' "$1" | xclip -selection clipboard
  elif command -v clip.exe >/dev/null 2>&1; then printf '%s' "$1" | clip.exe
  else return 1; fi
}

# on_server CMD: run CMD as root on the server with the operator key.
on_server() {
  ssh -i "$SSH_KEY_PATH" -o StrictHostKeyChecking=accept-new "root@$SERVER_IP" "$@"
}

# load KEY...: values the provisioning wizard saved; stop if one is missing.
load() {
  local k v
  for k in "$@"; do
    v=$(_existing "$k" || true)
    [[ -n "$v" ]] || { warn "$k is not in $ENV_FILE: run scripts/setup-beta-infra.sh first."; exit 1; }
    printf -v "$k" '%s' "$v"
  done
}

# generate KEY: a random hex password, kept across re-runs.
generate() {
  local v; v=$(_existing "$1" || true)
  if [[ -n "$v" ]]; then printf -v "$1" '%s' "$v"; else write_env "$1" "$(openssl rand -hex 24)"; fi
}

# container UUID: the running container of a Coolify resource; Coolify names
# them after the resource's UUID.
container() { on_server "docker ps -q --filter name=$1 | head -n1"; }

load DOMAIN SSH_KEY_PATH SERVER_IP SERVER_LOCATION COOLIFY_URL BACKUP_S3_LOCATION \
  RESEND_API_KEY MAIL_FROM SENTRY_DSN_API BETTER_AUTH_SECRET

banner "Homelibra beta deploy (#42)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "GitHub: images in GHCR"
say "Coolify pulls three images that CI pushes from main (.github/workflows/ci.yml, job images)."
while :; do
  missing=()
  for image in homelibra-postgres homelibra-api homelibra-web; do
    tags=$(gh api "/user/packages/container/$image/versions" -q '.[].metadata.container.tags[]' 2>/dev/null || true)
    if grep -qx main <<<"$tags"; then
      printf '  %s✓%s %s/%s:main\n' "$GREEN" "$RESET" "$IMAGES" "$image"
    else
      missing+=("$image")
    fi
  done
  (( ${#missing[@]} == 0 )) && break
  warn "Not found (or gh lacks read:packages): ${missing[*]}"
  step "Merge the #42 work into main and wait for CI's images job to pass."
  note "To give gh the scope: gh auth refresh -s read:packages"
  open_url "https://github.com/baspinarenes/homelibra/actions/workflows/ci.yml"
  confirm "Check again? (No continues anyway)" || break
done
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Google: production OAuth client"
if ! already_saved GOOGLE_CLIENT_ID GOOGLE_CLIENT_SECRET; then
  say "The API refuses to start in production without Google sign-in."
  open_url "https://console.cloud.google.com/apis/credentials"
  step "Pick the Homelibra project (the one development's client lives in)."
  step "'+ Create credentials' → OAuth client ID → Application type: Web application."
  step "Name: homelibra-production."
  step "Authorized JavaScript origins: https://$DOMAIN"
  step "Authorized redirect URIs: https://$DOMAIN/api/auth/callback/google → Create."
  ask_match ask GOOGLE_CLIENT_ID "Client ID:" '\.apps\.googleusercontent\.com$' "Client IDs end in .apps.googleusercontent.com."
  ask_match ask_secret GOOGLE_CLIENT_SECRET "Client secret (GOCSPX-…):" '^GOCSPX-' "Client secrets start with GOCSPX-."
  write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
  write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"
  step "Google Auth Platform → Audience: if it says Testing, 'Publish app'."
  note "Only email and profile are asked for, so publishing needs no Google review;"
  note "while Testing, only listed test users could sign in with Google."
  pause
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Hetzner Object Storage: covers bucket"
if ! already_saved COVERS_S3_BUCKET COVERS_S3_ACCESS_KEY_ID COVERS_S3_SECRET_ACCESS_KEY; then
  say "Covers go to a private bucket beside the server ($SERVER_LOCATION), without backup (ADR-0011)."
  open_url "https://console.hetzner.com/"
  step "Homelibra project → Object Storage → 'Create Bucket'."
  step "Location: $SERVER_LOCATION. Name: homelibra-covers (add a suffix if taken). Private."
  ask_match ask COVERS_S3_BUCKET "Bucket name [homelibra-covers]:" '^([a-z0-9][a-z0-9.-]{1,61}[a-z0-9])?$' "Lowercase letters, digits, dots and hyphens only."
  COVERS_S3_BUCKET="${COVERS_S3_BUCKET:-homelibra-covers}"
  step "Security → 'S3 Credentials' → 'Generate credentials', description homelibra-api-covers."
  warn "Hetzner credentials reach every bucket in the project, the backups too."
  note "A separate key at least lets you revoke the API's access alone."
  ask COVERS_S3_ACCESS_KEY_ID "Access key (top box):"
  ask_secret COVERS_S3_SECRET_ACCESS_KEY "Secret key (bottom box):"
  write_env COVERS_S3_ENDPOINT "https://$SERVER_LOCATION.your-objectstorage.com"
  write_env COVERS_S3_REGION "$SERVER_LOCATION"
  write_env COVERS_S3_BUCKET "$COVERS_S3_BUCKET"
  write_env COVERS_S3_ACCESS_KEY_ID "$COVERS_S3_ACCESS_KEY_ID"
  write_env COVERS_S3_SECRET_ACCESS_KEY "$COVERS_S3_SECRET_ACCESS_KEY"
fi
load COVERS_S3_ENDPOINT COVERS_S3_REGION

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Coolify: Postgres"
generate HOMELIBRA_OWNER_PASSWORD
generate HOMELIBRA_APP_PASSWORD
if ! already_saved DB_UUID; then
  open_url "$COOLIFY_URL/projects"
  step "Create a project Homelibra (or open it) → production → '+ New' → PostgreSQL."
  step "General → Image: $IMAGES/homelibra-postgres:main"
  step "Leave 'Initial Database' as postgres: our init script creates homelibra itself."
  step "Persistent Storage: the destination must be /var/lib/postgresql/data (PostgreSQL 17)."
  note "Coolify defaults to /var/lib/postgresql for 18; fix it before the first start."
  pause "Press Enter to put the environment variables on your clipboard."
  to_clipboard "HOMELIBRA_OWNER_PASSWORD=$HOMELIBRA_OWNER_PASSWORD
HOMELIBRA_APP_PASSWORD=$HOMELIBRA_APP_PASSWORD
HOMELIBRA_DATABASES=homelibra" \
    && note "Copied." || note "No clipboard tool: copy HOMELIBRA_* from $ENV_FILE."
  step "Environment Variables → 'Developer view' → paste → Save. Then 'Start'."
  step "The resource's URL ends in /database/<uuid>: copy that uuid."
  ask_match ask DB_UUID "Database UUID:" '^[a-z0-9]{8,}$' "Lowercase letters and digits, from the URL."
  write_env DB_UUID "$DB_UUID"
fi
say "Checking the roles on the server …"
until roles=$(on_server "docker exec $DB_UUID psql -U postgres -tAc \"select string_agg(rolname, ' ') from pg_roles where rolname like 'homelibra_%'\"" 2>/dev/null) \
  && [[ "$roles" == *homelibra_app* && "$roles" == *homelibra_owner* ]]; do
  warn "No homelibra_owner and homelibra_app yet (got: '${roles:-no container}')."
  note "If the database came up before the variables were saved, the init script didn't run:"
  note "stop it, delete its volume, start again."
  confirm "Check again?" || break
done
[[ "${roles:-}" == *homelibra_app* ]] && printf '  %s✓%s roles: %s\n' "$GREEN" "$RESET" "$roles"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Coolify: daily backups, 14 days"
say "Done on an earlier run? Press Enter through this stage."
open_url "$COOLIFY_URL"
step "Database homelibra-postgres → Backups → '+ Add'. Frequency: 0 3 * * * (daily, 03:00 UTC)."
step "Databases to back up: homelibra. 'Save to S3' on → storage hetzner-$BACKUP_S3_LOCATION-backups."
step "Retention, both Local and S3: Days to keep 14; Backups to keep and Maximum storage 0."
note "14 days of backups after 14 days of closure keep the 30-day deletion promise (#40)."
pause "Saved? Press Enter."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Coolify: the API"
if ! already_saved API_UUID; then
  open_url "$COOLIFY_URL/projects"
  step "Homelibra → production → '+ New' → Docker Image: $IMAGES/homelibra-api:main"
  step "Domains: https://$DOMAIN/api   Ports Exposes: 3000"
  step "Advanced: turn 'Strip Prefixes' off. The API's routes start with /api themselves."
  step "Healthcheck: enabled, path /api/health, port 3000."
  pause "Press Enter to put the environment variables on your clipboard."
  to_clipboard "NODE_ENV=production
DATABASE_URL=postgres://homelibra_app:$HOMELIBRA_APP_PASSWORD@$DB_UUID:5432/homelibra
MIGRATION_DATABASE_URL=postgres://homelibra_owner:$HOMELIBRA_OWNER_PASSWORD@$DB_UUID:5432/homelibra
BETTER_AUTH_URL=https://$DOMAIN
BETTER_AUTH_SECRET=$BETTER_AUTH_SECRET
RESEND_API_KEY=$RESEND_API_KEY
MAIL_FROM=$MAIL_FROM
GOOGLE_CLIENT_ID=$GOOGLE_CLIENT_ID
GOOGLE_CLIENT_SECRET=$GOOGLE_CLIENT_SECRET
TRUSTED_ORIGINS=homelibra://
COVERS_S3_ENDPOINT=$COVERS_S3_ENDPOINT
COVERS_S3_REGION=$COVERS_S3_REGION
COVERS_S3_BUCKET=$COVERS_S3_BUCKET
COVERS_S3_ACCESS_KEY_ID=$COVERS_S3_ACCESS_KEY_ID
COVERS_S3_SECRET_ACCESS_KEY=$COVERS_S3_SECRET_ACCESS_KEY
SENTRY_DSN=$SENTRY_DSN_API
SENTRY_ENVIRONMENT=production" \
    && note "Copied." || { warn "No clipboard tool; the values are in $ENV_FILE."; }
  step "Environment Variables → 'Developer view' → paste → Save → 'Deploy'."
  note "The container migrates as homelibra_owner, then serves as homelibra_app."
  step "The resource's URL ends in /application/<uuid>: copy that uuid."
  ask_match ask API_UUID "API UUID:" '^[a-z0-9]{8,}$' "Lowercase letters and digits, from the URL."
  write_env API_UUID "$API_UUID"
fi
pause "Deployment finished and healthy? Press Enter."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Coolify: the web app"
if ! already_saved WEB_UUID; then
  open_url "$COOLIFY_URL/projects"
  step "Homelibra → production → '+ New' → Docker Image: $IMAGES/homelibra-web:main"
  step "Domains: https://$DOMAIN   Ports Exposes: 80"
  step "Healthcheck: enabled, path /, port 80 → 'Deploy'."
  note "The more specific /api route keeps going to the API."
  step "The resource's URL ends in /application/<uuid>: copy that uuid."
  ask_match ask WEB_UUID "Web UUID:" '^[a-z0-9]{8,}$' "Lowercase letters and digits, from the URL."
  write_env WEB_UUID "$WEB_UUID"
fi
pause "Deployment finished? Press Enter."

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "GitHub: deploys from CI"
say "After pushing images, CI asks Coolify to redeploy the API and the web app."
if ! already_saved COOLIFY_TOKEN; then
  open_url "$COOLIFY_URL/security/api-tokens"
  step "If the API is off: Settings → Advanced → 'API Access' on."
  step "Keys & Tokens → API tokens: name github-deploy, permission deploy only → Create."
  ask_secret COOLIFY_TOKEN "Token:"
  write_env COOLIFY_TOKEN "$COOLIFY_TOKEN"
fi
set_secret COOLIFY_TOKEN "$COOLIFY_TOKEN"
set_var COOLIFY_URL "$COOLIFY_URL"
set_var COOLIFY_API_UUID "$API_UUID"
set_var COOLIFY_WEB_UUID "$WEB_UUID"
if confirm "Trigger a web deploy through the API now, as CI will?"; then
  curl -fsS -H "Authorization: Bearer $COOLIFY_TOKEN" "$COOLIFY_URL/api/v1/deploy?uuid=$WEB_UUID" \
    && printf '\n  %s✓%s Coolify accepted the deploy\n' "$GREEN" "$RESET" \
    || warn "Coolify refused it: check the token's permission and API Access."
fi
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Production: smoke test and your Invitation"
if [[ "$(curl -fsS "https://$DOMAIN/api/health" 2>/dev/null)" == ok ]]; then
  printf '  %s✓%s https://%s/api/health\n' "$GREEN" "$RESET" "$DOMAIN"
else
  warn "https://$DOMAIN/api/health doesn't answer ok: see the API's logs in Coolify."
  SKIPPED+=("API health on https://$DOMAIN")
fi
if curl -fsS "https://$DOMAIN/" 2>/dev/null | grep -q '<title>Homelibra'; then
  printf '  %s✓%s https://%s/ serves the web app\n' "$GREEN" "$RESET" "$DOMAIN"
else
  warn "https://$DOMAIN/ doesn't serve the web app yet."
  SKIPPED+=("web app on https://$DOMAIN")
fi
ask OPERATOR_EMAIL "Your email address, to invite [$(git config user.email)]:"
OPERATOR_EMAIL="${OPERATOR_EMAIL:-$(git config user.email)}"
write_env OPERATOR_EMAIL "$OPERATOR_EMAIL"
api=$(container "$API_UUID")
if [[ -n "$api" ]]; then
  on_server "docker exec $api tsx src/invite.ts add '$OPERATOR_EMAIL'" | sed 's/^/  /'
  note "Invite each beta reader the same way: docker exec <api container> tsx src/invite.ts add <email>"
else
  warn "No running API container named after $API_UUID."
  SKIPPED+=("invite $OPERATOR_EMAIL")
fi
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Cloudflare: mail to iletisim@$DOMAIN"
say "The app shows iletisim@$DOMAIN as its contact address; Resend only sends."
say "Done on an earlier run? Press Enter through this stage."
open_url "https://dash.cloudflare.com/?to=/:account/:zone/email/routing/overview"
step "Email Routing → 'Get started' / 'Enable'. Let it add its MX and TXT records."
note "Resend's MX lives on send.$DOMAIN, so the two don't collide."
step "Destination addresses: add your inbox and click the link Cloudflare emails you."
step "Routing rules → custom address iletisim@$DOMAIN → Send to your inbox → Save."
step "Send a test mail to iletisim@$DOMAIN from another account."
pause "It arrived? Press Enter."

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Production: sign in on the web"
open_url "https://$DOMAIN"
step "Enter $OPERATOR_EMAIL: a 6-digit code should arrive from $MAIL_FROM."
step "Sign in with it, then sign out and try 'Google ile devam et' too."
note "No code? Resend → Emails shows whether it was sent; the API's logs show why not."
confirm "Both sign-ins worked?" || SKIPPED+=("web sign-in on https://$DOMAIN")

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Backups: one restore drill"
say "A backup counts once it has been restored (#42). This restores the newest dump"
say "into a throwaway database beside production, compares every table, then drops it."
open_url "$COOLIFY_URL"
step "Database → Backups → the schedule → 'Backup Now'."
step "Wait for the run to show Success, with the S3 upload succeeded too."
pause "Done? Press Enter to find the dump on the server."
dump=$(on_server "find /data/coolify/backups -path '*$DB_UUID*' -name 'pg-dump-homelibra-*' | sort | tail -n1")
if [[ -z "$dump" ]]; then
  warn "No dump of homelibra under /data/coolify/backups for $DB_UUID."
  SKIPPED+=("restore drill")
elif confirm "Restore $dump into homelibra_restore_drill?"; then
  # One count per table, in the same order in both databases.
  counts="select string_agg(format('select %L as t, count(*) from public.%I', table_name, table_name), ' union all ' order by table_name) from information_schema.tables where table_schema = 'public' and table_type = 'BASE TABLE'"
  on_server "set -e
    docker cp '$dump' $DB_UUID:/tmp/drill.dmp
    docker exec $DB_UUID psql -U postgres -qc 'drop database if exists homelibra_restore_drill' -c 'create database homelibra_restore_drill owner homelibra_owner'
    docker exec $DB_UUID pg_restore -U postgres --exit-on-error -d homelibra_restore_drill /tmp/drill.dmp
    q=\$(docker exec $DB_UUID psql -U postgres -d homelibra -tAc \"$counts\")
    docker exec $DB_UUID psql -U postgres -d homelibra -tAc \"\$q order by 1\" > /tmp/live.txt
    docker exec $DB_UUID psql -U postgres -d homelibra_restore_drill -tAc \"\$q order by 1\" > /tmp/drill.txt
    docker exec $DB_UUID psql -U postgres -qc 'drop database homelibra_restore_drill'
    docker exec $DB_UUID rm /tmp/drill.dmp
    echo \"tables: \$(wc -l < /tmp/drill.txt)\"
    diff /tmp/live.txt /tmp/drill.txt && echo 'every table has the same row count' || echo 'counts differ: writes since the backup, or a broken restore'
    rm /tmp/live.txt /tmp/drill.txt" | sed 's/^/  /' \
    && write_env RESTORE_DRILL_AT "$(date -u +%Y-%m-%dT%H:%MZ) $(basename "$dump")" \
    || { warn "The restore failed; see the output above."; SKIPPED+=("restore drill"); }
else
  SKIPPED+=("restore drill")
fi
pause

# ── 13 ────────────────────────────────────────────────────────────────────
stage "EAS: the preview APK"
say "EAS builds the APK in the cloud (apps/app/eas.json, profile preview, channel preview)."
note "The first build asks to generate an Android keystore: answer yes; EAS keeps it."
note "Release builds call https://$DOMAIN (apps/app/src/lib/api-url.ts)."
if confirm "Start the build now (it waits in the queue, often 10–20 minutes)?"; then
  (cd apps/app && npx eas-cli@latest build --profile preview --platform android) \
    || { warn "The build failed; its page on expo.dev has the logs."; SKIPPED+=("preview APK"); }
else
  SKIPPED+=("preview APK: cd apps/app && npx eas-cli@latest build --profile preview --platform android")
fi
say "EAS Update channels:"
(cd apps/app && npx eas-cli@latest channel:list 2>/dev/null) | sed 's/^/  /' || true
if confirm "Create the production channel now, if it isn't listed?"; then
  (cd apps/app && npx eas-cli@latest channel:create production) || true
fi
pause

# ── 14 ────────────────────────────────────────────────────────────────────
stage "Android: install the APK and sign in"
open_url "https://expo.dev/accounts/enesbaspinar/projects/homelibra/builds"
step "Open the finished preview build on the phone (scan its QR code) → Install."
step "Allow the browser to install unknown apps when Android asks."
note "A phone with the dev build has the same package: uninstall that first."
step "Open Homelibra, sign in with the code sent to $OPERATOR_EMAIL."
step "Capture a Note, then check it on https://$DOMAIN."
confirm "Signed in on the phone against production?" || SKIPPED+=("APK sign-in on a phone")

finish
}

run_wizard "$@"; exit
